#include "AIRuntimeScratch.hpp"
namespace elysium::ai {bool AIRuntimeScratch::upsert(ActorAIState s){if(!s.actor)return false;rows_[s.actor]=std::move(s);return true;}void AIRuntimeScratch::sense(StableId id,Stimulus s,std::size_t max,std::uint64_t minTick){auto i=rows_.find(id);if(i==rows_.end())return;auto&v=i->second.stimuli;v.erase(std::remove_if(v.begin(),v.end(),[&](auto&x){return x.tick<minTick;}),v.end());v.push_back(s);std::stable_sort(v.begin(),v.end(),[](auto&a,auto&b){return a.importance==b.importance?a.source<b.source:a.importance>b.importance;});std::size_t n=0;for(auto it=v.begin();it!=v.end();){if(it->category==s.category&&++n>max)it=v.erase(it);else++it;}}bool AIRuntimeScratch::setPath(StableId id,PathHandle p,std::uint64_t nav,std::string&w){auto i=rows_.find(id);if(i==rows_.end()){w="unknown actor";return false;}if(p.navRevision!=nav){w="stale path";return false;}i->second.path=p;return true;}bool AIRuntimeScratch::invalidateIntent(StableId id,std::uint64_t r){auto i=rows_.find(id);if(i==rows_.end())return false;if(i->second.intent.sourceRevision<r){i->second.intent={};i->second.path.reset();return true;}return false;}std::optional<ActorAIState>AIRuntimeScratch::get(StableId id)const{auto i=rows_.find(id);if(i==rows_.end())return std::nullopt;return i->second;}}
